package com.harvestflow.registration.controller;
import com.harvestflow.registration.dto.request.*; import com.harvestflow.registration.dto.response.*; import com.harvestflow.registration.service.RegistrationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/auth/register") @RequiredArgsConstructor public class RegistrationController { private final RegistrationService service;
 @PostMapping public RegistrationSessionResponse start(@Valid @RequestBody BasicDetailsRequest r){return service.startRegistration(r);} @PostMapping("/mobile/send-otp") public OtpSentResponse mobile(@Valid @RequestBody SendMobileOtpRequest r){return service.sendMobileOtp(r);} @PostMapping("/mobile/verify-otp") public OtpVerifiedResponse mobileVerify(@Valid @RequestBody VerifyMobileOtpRequest r){return service.verifyMobileOtp(r);} @PostMapping("/aadhaar/send-otp") public OtpSentResponse aadhaar(@Valid @RequestBody SendAadhaarOtpRequest r){return service.sendAadhaarOtp(r);} @PostMapping("/aadhaar/verify-otp") public OtpVerifiedResponse aadhaarVerify(@Valid @RequestBody VerifyAadhaarOtpRequest r){return service.verifyAadhaarOtp(r);} @PostMapping("/role") public RegistrationSessionResponse role(@Valid @RequestBody RoleSelectionRequest r){return service.selectRole(r);} @PostMapping("/address") public RegistrationSessionResponse address(@Valid @RequestBody AddressRequest r){return service.submitAddress(r);}
 @PostMapping(value="/documents/khet-receipt",consumes="multipart/form-data") public DocumentUploadResponse receipt(@RequestParam String registrationToken,@RequestParam MultipartFile file){return service.uploadKhetReceipt(registrationToken,file);} @PostMapping(value="/documents/signature",consumes="multipart/form-data") public DocumentUploadResponse signature(@RequestParam String registrationToken,@RequestParam MultipartFile file){return service.uploadSignature(registrationToken,file);} @PostMapping(value="/documents/photo",consumes="multipart/form-data") public DocumentUploadResponse photo(@RequestParam String registrationToken,@RequestParam MultipartFile file){return service.uploadPhoto(registrationToken,file);} @PostMapping("/submit") public RegistrationCompleteResponse submit(@Valid @RequestBody SubmitRegistrationRequest r){return service.submit(r);} }
